A library is reusable code that doesn't hold its own state and is either inlined (internal functions) or deployed once and called via delegatecall (external functions) -- saving deployment gas across many contracts. OpenZeppelin's SafeERC20 and Math libraries are common examples.

EXAMPLE:
library MathUtils {
    function average(uint256 a, uint256 b) internal pure returns (uint256) {
        return (a & b) + (a ^ b) / 2; // avoids overflow vs. (a+b)/2
    }
}

contract Example {
    using MathUtils for uint256;

    function getAverage(uint256 x, uint256 y) external pure returns (uint256) {
        return x.average(y);
    }
}

