    uint256 public count;

    function increment() public {
        count += 1; // this exact contract deploys unchanged on most L2s
    }
}

body:
Bridges let assets or messages move between different blockchains, which don't natively communicate. Common designs: lock-and-mint (lock on chain A, mint a wrapped version on chain B) or liquidity-pool-based swaps.

EXAMPLE (conceptual lock-and-mint):
// On Chain A
function lockTokens(uint256 amount) external {
    token.transferFrom(msg.sender, address(this), amount);
    emit Locked(msg.sender, amount); // relayers watch for this event
}

// On Chain B (triggered by an off-chain relayer/oracle after seeing the lock event)
function mintWrapped(address to, uint256 amount) external onlyBridge {
    wrappedToken.mint(to, amount);
}

WHY IT MATTERS: Bridges have been the single largest source of DeFi hacks by dollar value -- because they concentrate enormous value behind trust assumptions (a multisig, a validator set, or a relayer) that are often weaker than the underlying blockchains they connect. Treat any bridge's security model as a first-class question, not an afterthought.

FURTHER READING:
- Ethereum.org, Bridges: https://ethereum.org/en/bridges/
- Chainalysis, Cross-chain bridge hacks (industry research): https://www.chainalysis.com/blog/

